export const colorNames = Object.keys(tokens.color);
export const inkNames = Object.keys(tokens.ink);
export const highlightNames = Object.keys(tokens.highlight);
export const tintNames = Object.keys(tokens.tint);
export const backdropNames = Object.keys(tokens.backdrop);

/** CSS custom property for a token, e.g. cssVar("color", "bg.canvas") -> var(--ds-bg-canvas). */
export function cssVar(group, name, part) {
  const n = name.replace(/\./g, "-");
  if (group === "color") return `var(--ds-${n})`;
  if (group === "tint") return `var(--ds-tint-${n}-${part ?? "fg"})`;
  return `var(--ds-${group}-${n})`;
}
